package com.cpf.starter.jms;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.messaging.jms") public class CpfJmsProperties {private boolean enabled;private String bindingName="jms";private boolean defaultBinding;private String destination;private boolean pubSubDomain;private boolean sessionTransacted=true;private int acknowledgementMode=2;private int maxPayloadBytes=1048576;
 public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getBindingName(){return bindingName;}public void setBindingName(String v){bindingName=v;}public boolean isDefaultBinding(){return defaultBinding;}public void setDefaultBinding(boolean v){defaultBinding=v;}public String getDestination(){return destination;}public void setDestination(String v){destination=v;}public boolean isPubSubDomain(){return pubSubDomain;}public void setPubSubDomain(boolean v){pubSubDomain=v;}public boolean isSessionTransacted(){return sessionTransacted;}public void setSessionTransacted(boolean v){sessionTransacted=v;}public int getAcknowledgementMode(){return acknowledgementMode;}public void setAcknowledgementMode(int v){acknowledgementMode=v;}public int getMaxPayloadBytes(){return maxPayloadBytes;}public void setMaxPayloadBytes(int v){maxPayloadBytes=v;}public void validate(){if(!enabled)return;if(bindingName==null||bindingName.isBlank()||destination==null||destination.isBlank())throw new IllegalStateException("JMS binding-name and destination are required");}}
